using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using StellarTool;
var root=Path.GetFullPath(Environment.GetEnvironmentVariable("STELLAR_TOOL_HOME")??Directory.GetCurrentDirectory());
var configPath=Path.Combine(root,"config.json");var tokenPath=Path.Combine(root,"bridge-token.txt");Directory.CreateDirectory(root);
JsonObject config=File.Exists(configPath)?ConfigRules.Validate(JsonNode.Parse(File.ReadAllText(configPath))!.AsObject()):ConfigRules.Defaults();
if(!File.Exists(configPath))File.WriteAllText(configPath,config.ToJsonString(new(){WriteIndented=true}));
if(!File.Exists(tokenPath))File.WriteAllText(tokenPath,Convert.ToHexString(RandomNumberGenerator.GetBytes(32)));
var token=File.ReadAllText(tokenPath).Trim();var cfgGate=new object();var store=new SnapshotStore();var inputStore=new InputSnapshotStore();
var active=config["server"]!.DeepClone();var host=active["host"]!.GetValue<string>();var management=active["managementPort"]!.GetValue<int>();var display=active["displayPort"]!.GetValue<int>();
var builder=WebApplication.CreateBuilder(args);builder.WebHost.ConfigureKestrel(o=>{o.Limits.MaxRequestBodySize=16*1024*1024;o.Listen(IPAddress.Parse(host),management);o.Listen(IPAddress.Parse(host),display);});
var app=builder.Build();app.UseWebSockets();app.Use(async(ctx,next)=>{ctx.Response.Headers["Cache-Control"]="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";await next();});
app.MapGet("/api/input",()=>Results.Json(inputStore.Get()));
app.MapGet("/api/input-stream",(HttpContext ctx)=>InputWebSocket.Handle(ctx,inputStore,app.Lifetime.ApplicationStopping));
app.MapGet("/api/state",(HttpContext ctx)=>Results.Json(store.Get(ctx.Request.Query["light"]!="1",ctx.Request.Query["judgement"]=="1")));
app.MapGet("/api/chart",(HttpContext ctx)=>store.Chart(ctx.Request.Query["session"]) is {} bytes?Results.Bytes(bytes,"application/json"):Results.NotFound());
app.MapGet("/api/config",()=>{lock(cfgGate)return Results.Json(config.DeepClone());});
bool IsManagement(HttpContext ctx)=>ctx.Connection.LocalPort==management;
bool ValidWrite(HttpContext ctx){if(!IsManagement(ctx)||ctx.Connection.RemoteIpAddress is not {} remote||!IPAddress.IsLoopback(remote)||!ctx.Request.HasJsonContentType())return false;var origin=ctx.Request.Headers.Origin.ToString();return origin.Length==0||origin==$"{ctx.Request.Scheme}://{ctx.Request.Host}";}
async Task<IResult> Save(HttpContext ctx,bool reset){if(!ValidWrite(ctx))return Results.StatusCode(403);try{var next=reset?ConfigRules.Defaults():ConfigRules.Validate((await JsonNode.ParseAsync(ctx.Request.Body))!.AsObject());lock(cfgGate){var temp=configPath+".tmp";File.WriteAllText(temp,next.ToJsonString(new(){WriteIndented=true}));File.Move(temp,configPath,true);config=next;}return Results.Json(new{ok=true,restartRequired=!JsonNode.DeepEquals(active,next["server"]),config=next});}catch(Exception e){return Results.BadRequest(new{error=e.Message});}}
app.MapPut("/api/config",(Func<HttpContext,Task<IResult>>)(ctx=>Save(ctx,false)));app.MapPost("/api/reset",(Func<HttpContext,Task<IResult>>)(ctx=>Save(ctx,true)));
app.MapPost("/api/ingest",async(HttpContext ctx)=>{if(!IsManagement(ctx)||ctx.Connection.RemoteIpAddress is not {} ip||!IPAddress.IsLoopback(ip)||!ctx.Request.HasJsonContentType())return Results.StatusCode(403);var supplied=Encoding.UTF8.GetBytes(ctx.Request.Headers["X-Stellar-Token"].ToString());if(!CryptographicOperations.FixedTimeEquals(supplied,Encoding.UTF8.GetBytes(token)))return Results.StatusCode(403);try{var needChart=store.Put((await JsonNode.ParseAsync(ctx.Request.Body))!.AsObject());ctx.Response.Headers["X-Stellar-Need-Chart"]=needChart?"1":"0";return Results.Ok();}catch(Exception e){return Results.BadRequest(new{error=e.Message});}});
app.MapPost("/api/input-ingest",async(HttpContext ctx)=>{if(!IsManagement(ctx)||ctx.Connection.RemoteIpAddress is not {} ip||!IPAddress.IsLoopback(ip)||!ctx.Request.HasJsonContentType())return Results.StatusCode(403);var supplied=Encoding.UTF8.GetBytes(ctx.Request.Headers["X-Stellar-Token"].ToString());if(!CryptographicOperations.FixedTimeEquals(supplied,Encoding.UTF8.GetBytes(token)))return Results.StatusCode(403);if(ctx.Request.ContentLength is not {} length||length<=0||length>InputSnapshotStore.MaxPayloadBytes)return Results.StatusCode(413);try{inputStore.Put((await JsonNode.ParseAsync(ctx.Request.Body))!.AsObject());ctx.Response.Headers["X-Stellar-Input-Events"]="1";return Results.Ok();}catch(Exception e){return Results.BadRequest(new{error=e.Message});}});
app.MapGet("/api/health",()=>Results.Json(new{ok=true,managementPort=management,displayPort=display,activeServer=active}));
app.MapGet("/assets/jackets/{file}",(HttpContext ctx,string file)=>{if(!System.Text.RegularExpressions.Regex.IsMatch(file,@"^UI_Jacket_[0-9]{6}\.png$"))return Results.NotFound();var configured=Environment.GetEnvironmentVariable("STELLAR_ASSETS_ZIP");var pointer=Path.Combine(root,"resource-path.txt");if(string.IsNullOrEmpty(configured)&&File.Exists(pointer))configured=File.ReadAllText(pointer).Trim();if(string.IsNullOrEmpty(configured))configured=Path.Combine(root,"jackets.zip");if(!File.Exists(configured))return Results.NotFound();try{using var zip=System.IO.Compression.ZipFile.OpenRead(configured);var entry=zip.GetEntry("assets/jackets/"+file);if(entry==null||entry.Length>10*1024*1024)return Results.NotFound();using var stream=entry.Open();using var memory=new MemoryStream();stream.CopyTo(memory);ctx.Response.Headers["Cache-Control"]="public,max-age=3600";return Results.File(memory.ToArray(),"image/png");}catch(Exception e){app.Logger.LogWarning("Jacket load failed: {Error}",e.Message);return Results.NotFound();}});
app.MapGet("/{**path}",(HttpContext ctx,string? path)=>{string file=path switch{null or ""=>IsManagement(ctx)?"admin.html":"index.html","rhythm" or "corner"=>"index.html","judgement" or "judgement/"=>"judgement.html","sensor" or "sensor/" or "keys" or "keys/"=>"input-overlay.html",_=>path};var web=Path.Combine(root,"web");var full=Path.GetFullPath(Path.Combine(web,file));if(!full.StartsWith(web+Path.DirectorySeparatorChar,StringComparison.Ordinal)||!File.Exists(full))return Results.NotFound();var type=Path.GetExtension(full) switch{".html"=>"text/html; charset=utf-8",".js" or ".mjs"=>"text/javascript; charset=utf-8",".css"=>"text/css",".json"=>"application/json",".ttf"=>"font/ttf",".png"=>"image/png",".svg"=>"image/svg+xml",_=>"application/octet-stream"};return Results.File(full,type);});
try{await app.RunAsync();}catch(Exception e){Console.Error.WriteLine("服务启动/运行失败（游戏主线程不受影响）："+e);Environment.ExitCode=1;}
